class Pt:
    def __init__(self, x):
        self.x = x
    def __eq__(self, other):
        if type(other) is not Pt:
            return NotImplemented
        return self.x == other.x
    def __hash__(self):
        return hash(self.x)
    def pair(self):
        return {self, Pt(self.x)}
